class Operations:
    """One method per operation. Each returns parsed JSON (bytes for binary, str for Box text)."""

    def call(self, op_id: str, **kw: Any) -> Any:  # implemented by RedX
        raise NotImplementedError

    def health(self, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Liveness, node id, role and version (no key needed). (GET /healthz; auth none; danger safe)"""
        return self.call("health", confirm=confirm, headers=headers)

    def whoami(self, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """The calling key's id, scope, database and prefix. (GET /v1/ui/whoami; auth key; danger safe)"""
        return self.call("whoami", confirm=confirm, headers=headers)

    def stats(self, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Engine and host counters of a database. (GET /v1/db/{db}/stats; auth read; danger safe)"""
        return self.call("stats", db=db, confirm=confirm, headers=headers)

    def list_databases(self, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Databases the key can see. (GET /v1/dbs; auth read; danger safe)"""
        return self.call("listDatabases", confirm=confirm, headers=headers)

    def create_database(self, *, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Create a database. (POST /v1/dbs; auth host-admin; danger admin)"""
        return self.call("createDatabase", body=body, confirm=confirm, headers=headers)

    def delete_database(self, *, db: Optional[str] = None, query: Optional[Dict[str, Any]] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Delete a database and all its files (irreversible). (DELETE /v1/db/{db}; auth host-admin; danger dangerous)"""
        return self.call("deleteDatabase", db=db, query=query, confirm=confirm, headers=headers)

    def validate(self, *, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Parse Box text, BoxQL or a policy and report line:col errors. (POST /v1/ui/validate; auth read; danger safe)"""
        return self.call("validate", body=body, confirm=confirm, headers=headers)

    def admin_status(self, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Dashboard status: version, data dir, TLS, cluster, warnings. (GET /v1/admin/status; auth host-admin; danger safe)"""
        return self.call("adminStatus", confirm=confirm, headers=headers)

    def admin_audit(self, *, query: Optional[Dict[str, Any]] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Newest audit events (never contain keys). (GET /v1/admin/audit; auth host-admin; danger safe)"""
        return self.call("adminAudit", query=query, confirm=confirm, headers=headers)

    def admin_config(self, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Effective configuration with secrets hidden. (GET /v1/admin/config; auth host-admin; danger safe)"""
        return self.call("adminConfig", confirm=confirm, headers=headers)

    def list_presets(self, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Settings presets with every value and reason. (GET /v1/admin/presets; auth host-admin; danger safe)"""
        return self.call("listPresets", confirm=confirm, headers=headers)

    def backup(self, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Online backup of all databases and keys as one archive (contains everything: store it safely). (GET /v1/admin/backup; auth host-admin; danger admin)"""
        return self.call("backup", confirm=confirm, headers=headers)

    def list_files(self, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Files of a database with type and size. (GET /v1/db/{db}/files; auth admin; danger safe)"""
        return self.call("listFiles", db=db, confirm=confirm, headers=headers)

    def list_keys(self, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Keys (ids, scopes, status; never the secrets). (GET /v1/keys; auth admin; danger safe)"""
        return self.call("listKeys", confirm=confirm, headers=headers)

    def get_key(self, id: str, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """One key's details. (GET /v1/keys/{id}; auth admin; danger safe)"""
        return self.call("getKey", id=id, confirm=confirm, headers=headers)

    def create_key(self, *, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Create an API key; the secret is returned once. (POST /v1/keys; auth admin; danger dangerous)"""
        return self.call("createKey", body=body, confirm=confirm, headers=headers)

    def revoke_key(self, id: str, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Revoke a key at once. (DELETE /v1/keys/{id}; auth admin; danger dangerous)"""
        return self.call("revokeKey", id=id, confirm=confirm, headers=headers)

    def rotate_key(self, id: str, *, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Issue a replacement key; the old one stops after the grace period. (POST /v1/keys/{id}/rotate; auth admin; danger dangerous)"""
        return self.call("rotateKey", id=id, body=body, confirm=confirm, headers=headers)

    def create_pairing_code(self, *, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """One-time sign-in code (5 min) that another device trades for a new key. (POST /v1/keys/pairing; auth admin; danger dangerous)"""
        return self.call("createPairingCode", body=body, confirm=confirm, headers=headers)

    def pair_exchange(self, *, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Trade a sign-in code for a key. (POST /v1/pair/exchange; auth none; danger write)"""
        return self.call("pairExchange", body=body, confirm=confirm, headers=headers)

    def get_path(self, path: str, *, db: Optional[str] = None, query: Optional[Dict[str, Any]] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Read the value at a path ({path, value} with value as Box text). (GET /v1/db/{db}/path/{path}; auth read; danger safe)"""
        return self.call("getPath", path=path, db=db, query=query, confirm=confirm, headers=headers)

    def get_path_box(self, path: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Read the value at a path as raw Box text. (GET /v1/db/{db}/path/{path}; auth read; danger safe)"""
        return self.call("getPathBox", path=path, db=db, confirm=confirm, headers=headers)

    def set_path(self, path: str, *, db: Optional[str] = None, body: Any = None, query: Optional[Dict[str, Any]] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Write a value (JSON envelope or Box text) with optional TTL. (PUT /v1/db/{db}/path/{path}; auth write; danger write)"""
        return self.call("setPath", path=path, db=db, body=body, query=query, confirm=confirm, headers=headers)

    def delete_path(self, path: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Delete the value at a path. (DELETE /v1/db/{db}/path/{path}; auth write; danger write)"""
        return self.call("deletePath", path=path, db=db, confirm=confirm, headers=headers)

    def path_query(self, *, db: Optional[str] = None, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Path-pattern query, e.g. file:Box[ID=*].Name. (POST /v1/db/{db}/query; auth read; danger safe)"""
        return self.call("pathQuery", db=db, body=body, confirm=confirm, headers=headers)

    def bx(self, *, db: Optional[str] = None, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Run one BoxQL command or {Tx[]} transaction with $params. (POST /v1/db/{db}/bx; auth read; danger write)"""
        return self.call("bx", db=db, body=body, confirm=confirm, headers=headers)

    def list_packs(self, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """File packs of a database. (GET /v1/db/{db}/pack; auth read; danger safe)"""
        return self.call("listPacks", db=db, confirm=confirm, headers=headers)

    def pack_list(self, pack: str, folder: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """List a folder of a pack. (GET /v1/db/{db}/pack/{pack}/ls/{folder}; auth read; danger safe)"""
        return self.call("packList", pack=pack, folder=folder, db=db, confirm=confirm, headers=headers)

    def pack_stat(self, pack: str, file: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """One file's size, hash and type. (GET /v1/db/{db}/pack/{pack}/stat/{file}; auth read; danger safe)"""
        return self.call("packStat", pack=pack, file=file, db=db, confirm=confirm, headers=headers)

    def pack_get(self, pack: str, file: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Download a file (HTTP Range supported). (GET /v1/db/{db}/pack/{pack}/file/{file}; auth read; danger safe)"""
        return self.call("packGet", pack=pack, file=file, db=db, confirm=confirm, headers=headers)

    def pack_put(self, pack: str, file: str, *, db: Optional[str] = None, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Upload a file (streamed; X-Redx-SHA256 verified). (PUT /v1/db/{db}/pack/{pack}/file/{file}; auth write; danger write)"""
        return self.call("packPut", pack=pack, file=file, db=db, body=body, confirm=confirm, headers=headers)

    def pack_delete(self, pack: str, file: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Delete a file. (DELETE /v1/db/{db}/pack/{pack}/file/{file}; auth write; danger write)"""
        return self.call("packDelete", pack=pack, file=file, db=db, confirm=confirm, headers=headers)

    def pack_gc(self, pack: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Free chunks of deleted or replaced files. (POST /v1/db/{db}/pack/{pack}/gc; auth admin; danger admin)"""
        return self.call("packGc", pack=pack, db=db, confirm=confirm, headers=headers)

    def pack_fsck(self, pack: str, *, db: Optional[str] = None, query: Optional[Dict[str, Any]] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Integrity report (changes nothing). (GET /v1/db/{db}/pack/{pack}/fsck; auth admin; danger safe)"""
        return self.call("packFsck", pack=pack, db=db, query=query, confirm=confirm, headers=headers)

    def list_media(self, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Media libraries of a database. (GET /v1/db/{db}/media; auth read; danger safe)"""
        return self.call("listMedia", db=db, confirm=confirm, headers=headers)

    def media_list(self, lib: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Items of a media library. (GET /v1/db/{db}/media/{lib}; auth read; danger safe)"""
        return self.call("mediaList", lib=lib, db=db, confirm=confirm, headers=headers)

    def media_stat(self, lib: str, name: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """One item's manifest. (GET /v1/db/{db}/media/{lib}/stat/{name}; auth read; danger safe)"""
        return self.call("mediaStat", lib=lib, name=name, db=db, confirm=confirm, headers=headers)

    def media_get(self, lib: str, name: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Download an item (HTTP Range supported). (GET /v1/db/{db}/media/{lib}/file/{name}; auth read; danger safe)"""
        return self.call("mediaGet", lib=lib, name=name, db=db, confirm=confirm, headers=headers)

    def media_put(self, lib: str, name: str, *, db: Optional[str] = None, body: Any = None, query: Optional[Dict[str, Any]] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Upload an item (?type= declares the media type). (PUT /v1/db/{db}/media/{lib}/file/{name}; auth write; danger write)"""
        return self.call("mediaPut", lib=lib, name=name, db=db, body=body, query=query, confirm=confirm, headers=headers)

    def media_delete(self, lib: str, name: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Delete an item. (DELETE /v1/db/{db}/media/{lib}/file/{name}; auth write; danger write)"""
        return self.call("mediaDelete", lib=lib, name=name, db=db, confirm=confirm, headers=headers)

    def list_indexes(self, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Index sets of a database. (GET /v1/db/{db}/idx; auth read; danger safe)"""
        return self.call("listIndexes", db=db, confirm=confirm, headers=headers)

    def index_query(self, set: str, index: str, *, db: Optional[str] = None, query: Optional[Dict[str, Any]] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Query an index (exact, prefix, range, text). (GET /v1/db/{db}/idx/{set}/{index}/query; auth read; danger safe)"""
        return self.call("indexQuery", set=set, index=index, db=db, query=query, confirm=confirm, headers=headers)

    def define_index(self, set: str, *, db: Optional[str] = None, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Define or replace an index set (Box text). (PUT /v1/db/{db}/idx/{set}; auth admin; danger admin)"""
        return self.call("defineIndex", set=set, db=db, body=body, confirm=confirm, headers=headers)

    def drop_index(self, set: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Drop an index set (the data stays). (DELETE /v1/db/{db}/idx/{set}; auth admin; danger admin)"""
        return self.call("dropIndex", set=set, db=db, confirm=confirm, headers=headers)

    def rebuild_index(self, set: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Rebuild an index set from the data. (POST /v1/db/{db}/idx/{set}/rebuild; auth admin; danger admin)"""
        return self.call("rebuildIndex", set=set, db=db, confirm=confirm, headers=headers)

    def check_index(self, set: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Compare an index set with the data. (GET /v1/db/{db}/idx/{set}/check; auth read; danger safe)"""
        return self.call("checkIndex", set=set, db=db, confirm=confirm, headers=headers)

    def get_rules(self, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Pulse rules and pending timers. (GET /v1/db/{db}/pulse; auth read; danger safe)"""
        return self.call("getRules", db=db, confirm=confirm, headers=headers)

    def put_rules(self, *, db: Optional[str] = None, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Replace the rule set (Box text, validated first). (PUT /v1/db/{db}/pulse; auth admin; danger admin)"""
        return self.call("putRules", db=db, body=body, confirm=confirm, headers=headers)

    def delete_rules(self, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Remove all rules. (DELETE /v1/db/{db}/pulse; auth admin; danger admin)"""
        return self.call("deleteRules", db=db, confirm=confirm, headers=headers)

    def get_policy(self, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Access policy summary (source for admins). (GET /v1/db/{db}/sec; auth read; danger safe)"""
        return self.call("getPolicy", db=db, confirm=confirm, headers=headers)

    def put_policy(self, *, db: Optional[str] = None, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Replace the access policy (changes who can read what). (PUT /v1/db/{db}/sec; auth admin; danger dangerous)"""
        return self.call("putPolicy", db=db, body=body, confirm=confirm, headers=headers)

    def delete_policy(self, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Remove the access policy. (DELETE /v1/db/{db}/sec; auth admin; danger dangerous)"""
        return self.call("deletePolicy", db=db, confirm=confirm, headers=headers)

    def list_scripts(self, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Script files of a database. (GET /v1/db/{db}/code; auth read; danger safe)"""
        return self.call("listScripts", db=db, confirm=confirm, headers=headers)

    def put_script(self, file: str, *, db: Optional[str] = None, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Define or replace a script file. (PUT /v1/db/{db}/code/file/{file}; auth admin; danger admin)"""
        return self.call("putScript", file=file, db=db, body=body, confirm=confirm, headers=headers)

    def delete_script(self, file: str, *, db: Optional[str] = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Delete a script file. (DELETE /v1/db/{db}/code/file/{file}; auth admin; danger admin)"""
        return self.call("deleteScript", file=file, db=db, confirm=confirm, headers=headers)

    def run_script(self, script: str, *, db: Optional[str] = None, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Run a script with arguments. (POST /v1/db/{db}/code/run/{script}; auth write; danger write)"""
        return self.call("runScript", script=script, db=db, body=body, confirm=confirm, headers=headers)

    def cluster_status(self, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Role, leader, members, replication offsets, fence. (GET /v1/cluster/status; auth host-admin; danger safe)"""
        return self.call("clusterStatus", confirm=confirm, headers=headers)

    def create_join_token(self, *, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Join token or pairing code that lets a node join and receive all data. (POST /v1/cluster/join-token; auth host-admin; danger dangerous)"""
        return self.call("createJoinToken", body=body, confirm=confirm, headers=headers)

    def promote(self, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Make this follower the leader (fences the old leader; unreplicated writes are lost). (POST /v1/cluster/promote; auth host-admin; danger dangerous)"""
        return self.call("promote", confirm=confirm, headers=headers)

    def repoint(self, *, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Make this node follow another leader (its own un-replicated writes are discarded). (POST /v1/cluster/leader; auth host-admin; danger dangerous)"""
        return self.call("repoint", body=body, confirm=confirm, headers=headers)

    def connect_start(self, *, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Register an app's connect request (what the console does with a link). (POST /v1/connect/start; auth host-admin; danger admin)"""
        return self.call("connectStart", body=body, confirm=confirm, headers=headers)

    def connect_pending(self, *, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Open connect requests. (GET /v1/connect/pending; auth host-admin; danger safe)"""
        return self.call("connectPending", confirm=confirm, headers=headers)

    def connect_approve(self, *, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Approve: creates the workspace and a one-time code for the app's key. (POST /v1/connect/approve; auth host-admin; danger dangerous)"""
        return self.call("connectApprove", body=body, confirm=confirm, headers=headers)

    def connect_deny(self, *, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """Deny an open request. (POST /v1/connect/deny; auth host-admin; danger write)"""
        return self.call("connectDeny", body=body, confirm=confirm, headers=headers)

    def connect_exchange(self, *, body: Any = None, confirm: bool = False, headers: Optional[Dict[str, str]] = None) -> Any:
        """App side: trade the code plus PKCE verifier for the workspace key. (POST /v1/connect/exchange; auth none; danger write)"""
        return self.call("connectExchange", body=body, confirm=confirm, headers=headers)

